'events', 'CREATE TABLE `events` (\n  `id` int NOT NULL AUTO_INCREMENT,\n  `title` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL,\n  `description` text COLLATE utf8mb3_unicode_ci,\n  `short_description` text COLLATE utf8mb3_unicode_ci,\n  `category` varchar(100) COLLATE utf8mb3_unicode_ci NOT NULL,\n  `status` enum(\'upcoming\',\'completed\') COLLATE utf8mb3_unicode_ci NOT NULL,\n  `event_date` date NOT NULL,\n  `event_time` varchar(100) COLLATE utf8mb3_unicode_ci DEFAULT NULL,\n  `location` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,\n  `duration` varchar(100) COLLATE utf8mb3_unicode_ci DEFAULT NULL,\n  `image_path` varchar(500) COLLATE utf8mb3_unicode_ci DEFAULT NULL,\n  `event_page_url` varchar(500) COLLATE utf8mb3_unicode_ci DEFAULT NULL,\n  `year` varchar(10) COLLATE utf8mb3_unicode_ci NOT NULL,\n  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,\n  `session_year` varchar(20) COLLATE utf8mb3_unicode_ci DEFAULT NULL,\n  `event_objective` text COLLATE utf8mb3_unicode_ci,\n  `event_highlights` text COLLATE utf8mb3_unicode_ci,\n  `schedule` text COLLATE utf8mb3_unicode_ci,\n  `technologies` text COLLATE utf8mb3_unicode_ci,\n  `coordinators` text COLLATE utf8mb3_unicode_ci,\n  `stats` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,\n  `long_description` text COLLATE utf8mb3_unicode_ci,\n  `event_agenda` text COLLATE utf8mb3_unicode_ci,\n  `event_technologies` text COLLATE utf8mb3_unicode_ci,\n  `event_coordinators` text COLLATE utf8mb3_unicode_ci,\n  `event_stats` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,\n  `gallery_images` text COLLATE utf8mb3_unicode_ci,\n  PRIMARY KEY (`id`)\n) ENGINE=InnoDB AUTO_INCREMENT=89 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci'
